pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        value = bound(value, 0, 1e18);
        uint256 countBefore = c.depositsCount();
        // Attempt call, may revert if target rejects ETH
        (bool ok, ) = address(c).call{value: value}(
            abi.encodeWithSignature("sendMoney(address,uint256)", target, value)
        );
        // Only consider cases where call succeeds (no revert from require)
        vm.assume(ok);
        uint256 countAfter = c.depositsCount();
        // The general rule: depositsCount increments by exactly 1 per successful sendMoney call
        assertTrue(countAfter == countBefore + 1);
    }
}

