pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        // Bound value to avoid overflow and ensure meaningful test
        vm.assume(value > 0 && value <= address(c).balance + 1 ether);
        vm.assume(target != address(0));
        vm.assume(target != address(c));

        uint256 balanceBefore = address(c).balance;

        // Call sendMoney
        c.sendMoney(target, value);

        // Check the rule: balance should decrease by exactly value (since target is not self, no fallback is triggered on C)
        // Note: This is the general rule for the reference contract
        // The buggy version will fail because withdrawAll deducts an extra 1 wei
        assertTrue(address(c).balance <= balanceBefore - value);
    }
}

