pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0) && value > 0 && value <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        uint256 receiverBefore = target.balance;
        c.sendMoney(target, value);
        uint256 balanceAfter = address(c).balance;
        uint256 receiverAfter = target.balance;
        // The rule: the change in contract balance equals -(value - (receiverAfter - receiverBefore)) if target == address(c), else equals -value
        if (target == address(c)) {
            assertTrue(balanceAfter - balanceBefore == (receiverAfter - receiverBefore) - value);
        } else {
            assertTrue(balanceAfter - balanceBefore == -int256(value));
        }
    }
}

