        vm.assume(target != address(0));
        value = bound(value, 1, address(c).balance);

        uint256 ownerBalanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.deal(address(c), contractBalanceBefore);
        (bool success, ) = address(c).call(abi.encodeCall(c.sendMoney, (target, value)));

        bool reverted = !success;
        uint256 ownerBalanceAfter = address(this).balance;

        assertTrue(ownerBalanceAfter >= ownerBalanceBefore - contractBalanceBefore || reverted);
    }
}

